def lawvere_diagonal(phi, f, domain_size):
    diagonal = lambda x: f(phi(x)(x))
    for a in range(domain_size):
        phi_a = phi(a)
        if all(phi_a(x) == diagonal(x) for x in range(domain_size)):
            return phi_a(a)
    return None

def iterate_self_observation(observe, x0, max_iter=100):
    x = x0
    for i in range(1, max_iter + 1):
        x_new = observe(x)
        if x_new == x:
            return x_new, i
        x = x_new
    return x, max_iter

def reflective_overhead(n):
    if n <= 1: return max(n, 0)
    return n ** (n - 1)
